@* Interactive warehouse selector — rendered with InteractiveServer so it can handle change events
   even though the parent MainLayout is static. *@
@rendermode InteractiveServer
@inject WarehouseState Warehouse
@inject InventoryAlertService AlertService
@implements IDisposable

<div class="warehouse-selector d-flex align-items-center gap-2">
    <label class="form-label mb-0 fw-semibold text-nowrap" for="warehouseSelect">Site:</label>
    <select id="warehouseSelect" class="form-select form-select-sm" style="width: auto;"
            value="@Warehouse.CurrentWarehouseId" @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.Warehouses)
        {
            <option value="@wh.Key">@wh.Value</option>
        }
    </select>
</div>

@code {
    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString() ?? "WH-001";
        Warehouse.SetWarehouse(newId);
        // Immediately refresh alerts for the new warehouse
        await AlertService.RefreshAsync();
    }

    public void Dispose() { }
}

@* Alert badge that subscribes to InventoryAlertService and updates when new data arrives.
   Must be interactive to receive background-thread notifications. *@
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable

<span class="badge @BadgeClass rounded-pill">@AlertService.LowStockCount</span>

@code {
    private Action? _handler;

    private string BadgeClass => AlertService.LowStockCount switch
    {
        0 => "bg-success",
        <= 5 => "bg-warning text-dark",
        _ => "bg-danger"
    };

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertDataChanged += _handler;
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= _handler;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@inject WarehouseState Warehouse
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard — @Warehouse.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Site</h5>
        <p class="card-text fs-5">
            <strong>@Warehouse.CurrentWarehouseName</strong>
            <span class="text-muted ms-2">(@Warehouse.CurrentWarehouseId)</span>
        </p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">
            Low Stock Alerts
            <span class="badge @AlertBadgeClass rounded-pill ms-2">@AlertService.LowStockCount</span>
        </h5>
        <p class="card-text text-muted">
            Polling every 10 seconds for items below minimum stock levels.
        </p>
        <p class="card-text">
            @if (AlertService.LowStockCount == 0)
            {
                <span class="text-success">✓ All items are above minimum levels.</span>
            }
            else
            {
                <span class="text-danger">⚠ @AlertService.LowStockCount item(s) need restocking.</span>
            }
        </p>
        <small class="text-muted">Last checked: @_lastChecked.ToString("HH:mm:ss")</small>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;
    private DateTime _lastChecked = DateTime.Now;

    private string AlertBadgeClass => AlertService.LowStockCount switch
    {
        0 => "bg-success",
        <= 5 => "bg-warning text-dark",
        _ => "bg-danger"
    };

    protected override void OnInitialized()
    {
        // Subscribe to alert changes (fires from background polling thread)
        _alertHandler = () => InvokeAsync(() =>
        {
            _lastChecked = DateTime.Now;
            StateHasChanged();
        });
        AlertService.OnAlertDataChanged += _alertHandler;

        // Subscribe to warehouse changes (fires from Blazor sync context)
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        Warehouse.OnChange += _warehouseHandler;

        // Start polling while this page is visible
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= _alertHandler;
        Warehouse.OnChange -= _warehouseHandler;
        AlertService.StopPolling();
    }
}

