+   Must be interactive to receive background-thread notifications. *@
+@rendermode InteractiveServer
+@inject InventoryAlertService AlertService
+@implements IDisposable
+
+<span class="badge @BadgeClass rounded-pill">@AlertService.LowStockCount</span>
+
+@code {
+    private Action? _handler;
+
+    private string BadgeClass => AlertService.LowStockCount switch
+    {
+        0 => "bg-success",
+        <= 5 => "bg-warning text-dark",
+        _ => "bg-danger"
+    };
+
+    protected override void OnInitialized()
+    {
+        _handler = () => InvokeAsync(StateHasChanged);
+        AlertService.OnAlertDataChanged += _handler;
+    }
+
+    public void Dispose()
+    {
+        AlertService.OnAlertDataChanged -= _handler;
+    }
+}
+

